from typing import Callable

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def affine_sum_invariant(p: int, a: int, b: int, f: Callable[[int], int]) -> bool:
    """Verify sum_x f(a*x+b) == sum_x f(x) over Z_p for prime p, a != 0."""
    assert is_prime(p) and a % p != 0
    base = sum(f(x % p) for x in range(p))
    shifted = sum(f((a * x + b) % p) for x in range(p))
    return base == shifted

if __name__ == "__main__":
    f = lambda x: (x * x + 3 * x + 1) % 7
    for a in range(1, 7):
        for b in range(7):
            assert affine_sum_invariant(7, a, b, f)
    print("affine summation invariant verified for all a != 0 over Z_7")
